select
  `r13`.`c0` as `country`,
  cast(`r13`.`c1` as decimal(38, 10)) as `order_price_p75`
from
  (
    select
      `r12`.`c0` as `c0`,
      cast(
        (
          max(
            case
              when `r12`.`rn` = floor(
                (1 + cast(? as decimal(38, 10)) * (`r12`.`n` - 1))
              )
              and `r12`.`n` > 0 then `r12`.`v`
            end
          ) + (
            max(
              case
                when `r12`.`rn` = ceil(
                  (1 + cast(? as decimal(38, 10)) * (`r12`.`n` - 1))
                )
                and `r12`.`n` > 0 then `r12`.`v`
              end
            ) - max(
              case
                when `r12`.`rn` = floor(
                  (1 + cast(? as decimal(38, 10)) * (`r12`.`n` - 1))
                )
                and `r12`.`n` > 0 then `r12`.`v`
              end
            )
          ) * max(
            (1 + cast(? as decimal(38, 10)) * (`r12`.`n` - 1)) - floor(
              (1 + cast(? as decimal(38, 10)) * (`r12`.`n` - 1))
            )
          )
        ) as decimal(38, 10)
      ) as `c1`
    from
      (
        select
          `r1`.`c0` as `c0`,
          cast(`r1`.`c1` as decimal(38, 10)) as v,
          row_number() over (
            partition by
              `r1`.`c0`
            order by
              case
                when cast(`r1`.`c1` as decimal(38, 10)) is null then 1
                else 0
              end,
              cast(`r1`.`c1` as decimal(38, 10))
          ) as rn,
          count(cast(`r1`.`c1` as decimal(38, 10))) over (
            partition by
              `r1`.`c0`
          ) as n
        from
          (
            select
              `r2`.`c2` as `c0`,
              `r2`.`c4` as `c1`
            from
              (
                select
                  `r3`.`c0` as `c0`,
                  `r3`.`c1` as `c1`,
                  `r3`.`c2` as `c2`,
                  `r11`.`c0` as `c3`,
                  `r11`.`c1` as `c4`,
                  `r11`.`c2` as `c5`
                from
                  (
                    select
                      `customers`.`customer_id` as `c0`,
                      `customers`.`city` as `c1`,
                      `customers`.`country` as `c2`
                    from
                      `customers`
                  ) as `r3`
                  inner join (
                    select
                      `r5`.`c2` as `c0`,
                      cast(
                        coalesce(`r5`.`c7`, cast(? as signed)) as decimal(38, 10)
                      ) as `c1`,
                      cast(
                        coalesce(`r5`.`c5`, cast(? as signed)) as decimal(38, 10)
                      ) as `c2`
                    from
                      (
                        select
                          `r6`.`c0` as `c0`,
                          `r6`.`c1` as `c1`,
                          `r6`.`c2` as `c2`,
                          `r6`.`c3` as `c3`,
                          `r6`.`c4` as `c4`,
                          `r6`.`c5` as `c5`,
                          `r10`.`c0` as `c6`,
                          `r10`.`c1` as `c7`
                        from
                          (
                            select
                              `orders`.`order_id` as `c0`,
                              `orders`.`order_date` as `c1`,
                              `orders`.`customer_id` as `c2`,
                              `orders`.`employee_id` as `c3`,
                              `orders`.`shipped_date` as `c4`,
                              cast(`orders`.`freight` as decimal(38, 10)) as `c5`
                            from
                              `orders`
                          ) as `r6`
                          left join (
                            select
                              `order_details`.`order_id` as `c0`,
                              cast(
                                sum(
                                  cast(
                                    cast(
                                      (
                                        cast(
                                          cast(
                                            (
                                              cast(
                                                cast(`order_details`.`unit_price` as decimal(38, 10)) as decimal(38, 10)
                                              ) * cast(`order_details`.`quantity` as decimal(38, 10))
                                            ) as decimal(38, 10)
                                          ) as decimal(38, 10)
                                        ) * cast(
                                          cast(
                                            (
                                              cast(cast(? as signed) as decimal(38, 10)) - cast(
                                                cast(`order_details`.`discount` as decimal(38, 10)) as decimal(38, 10)
