                                            ) as decimal(38, 10)
                                          ) as decimal(38, 10)
                                        )
                                      ) as decimal(38, 10)
                                    ) as decimal(38, 10)
                                  )
                                ) as decimal(38, 10)
                              ) as `c1`
                            from
                              `order_details`
                            group by
                              `order_details`.`order_id`
                          ) as `r10` on (`r6`.`c0` = `r10`.`c0`)
                      ) as `r5`
                  ) as `r11` on (
                    cast(`r3`.`c0` as binary) = cast(`r11`.`c0` as binary)
